(()=>{"use strict";window.CorsReceiverCoordinates={fromReceiver(e,i=!1){if(e?.message!=="UBX")return this.fromUnicore(e,i);if(e.state!=="ok"||e.position_type!=="FIXEDPOS"||e.datum!=="WGS84"||e.altitude_reference!=="ELLIPSOID")return null;const{lat:t,lon:r,alt:s}=e;return[t,r,s].some(u=>typeof u!="string"||!/^-?\d+(?:\.\d+)?$/.test(u)||!Number.isFinite(Number(u)))||Math.abs(Number(t))>90||Math.abs(Number(r))>180?null:{lat:t,lon:r,alt:s,heightMsl:s,undulation:"0.0000",source:"UBX",isBaseFixed:!0}},fromUnicore(e,i=!1){if(e?.state!=="ok"||e.position_type!=="FIXEDPOS"&&!(i&&e.position_type==="SINGLE")||typeof e.raw!="string"||!e.raw.startsWith("#BESTNAVA,"))return null;const t=e.raw.split(";")[1]?.split("*")[0].split(",");if(!t||t[0]!=="SOL_COMPUTED"||t[1]!==e.position_type||t[6]!=="WGS84")return null;const r=t.slice(2,6).map(l=>l.trim());if(r.length!==4||r.some(l=>!/^-?\d+(?:\.\d+)?$/.test(l)||!Number.isFinite(Number(l))))return null;const[s,u,n,a]=r;if(Math.abs(Number(s))>90||Math.abs(Number(u))>180)return null;const m=Number(n)+Number(a);return Number.isFinite(m)?{lat:s,lon:u,alt:m.toFixed(4),heightMsl:n,undulation:a,isBaseFixed:e.position_type==="FIXEDPOS"}:null}}})();
